window.__BUNDLE__={"generatedAt":"2026-10-05T06:10:31.958407+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-28","archiveCutoff":"2021-10-06","addedToday":383,"addedThisRun":383,"fetchStats":{"hf":273,"arxiv":1866,"total":2139},"freshness":{"latestPaperDate":"2026-10-05","latestPublishedDate":"2026-10-05","latestBatchCount":335,"newInLast24h":383,"newInLast48h":383},"historyTotal":20449,"topicCounts":{"Multi-Agent":2482,"Evaluation":11054,"Planning":1585,"Memory":414,"Code Agent":811,"Interpretability":732,"Agentic RAG":1306,"Agentic Search":1676,"RL for LLM":1177,"Reasoning":5714,"Hallucination":1025,"Post-Training":2383,"Alignment":2729,"World Model":344,"Tool Use":1254,"Agent Safety":2408,"Computer Use":297,"Reflection":724,"VLM Training":1506,"LLM Training":2523,"Fine-tuning":3132,"Multimodal Agent":117,"Agent Framework":824,"Error Attribution":128,"Data Engine":410},"count":36,"recentTotal":3550,"archiveCount":0,"archiveTotal":16899,"sources":{"hf":114,"arxiv":3436,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"id":"arxiv:2610.03632","pdf":"https://arxiv.org/pdf/2610.03632.pdf","submittedDate":"2026-10-02","source":"hf","arxiv":"https://arxiv.org/abs/2610.03632","tags":["Agentic RAG","Agentic Search","Evaluation","Alignment","World Model"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03632","authors":["Yiqi Liu","Ruifeng Yuan","Yang Wang","Long Li","Fengyu Cai","Hou Pong Chan","Jialin Yu","Hao Zhang","Chenghua Lin","Chenghao Xiao"],"hfUrl":"https://huggingface.co/papers/2610.03632","topics":["Agentic RAG","Agentic Search","Evaluation","Alignment","World Model"],"date":"2026-10-05","upvotes":15,"title":"World Embedding Benchmark","abstract":"Physical fidelity has received increasing attention in world models and video generation, yet how video representations encode physical information remains less understood. We introduce the World Embedding Benchmark, comprising 8,000 controlled simulation cases from 80 families spanning fluid mechanics, solid mechanics, dynamics, and optics & electromagnetism. Each case pairs a rendered video with simulation-derived physical annotations, supporting three complementary tasks: text-video retrieval, physical-property regression, and multiple-choice video-description pair classification. We use these tasks to distinguish cross-modal physical alignment from the recoverability of quantitative physical information. Evaluated pre-trained omnimodal embedding models show weak retrieval and near-chance within-family pair classification, while lightweight probes recover useful physical information f"},{"id":"arxiv:2610.02826","pdf":"https://arxiv.org/pdf/2610.02826.pdf","submittedDate":"2026-10-02","source":"hf","arxiv":"https://arxiv.org/abs/2610.02826","tags":["LLM Training"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02826","authors":["Zongxia Li","Yucheng Shi","Zhongzhi Li","Junyao Yang","Ruhan Wang","Chengsong Huang","Fuxiao Liu","Haitao Mi","Jordan Boyd-Graber","LeoweiLiang"],"hfUrl":"https://huggingface.co/papers/2610.02826","topics":["LLM Training"],"date":"2026-10-05","upvotes":12,"title":"Scaling Trajectories for Complex Tasks through Recursive Self-Rewrite","abstract":"Successful trajectories on difficult tasks provide valuable supervision for model improvement, but specialized harnesses introduce interventions that may be unavailable during deployment. We propose Recursive Self-Rewrite (RSR), a framework that uses one base model, Qwen-3.8-27B, to discover successful solutions under diverse harnesses and reconstruct them as training trajectories under a general harness. A planner extracts procedures into runbooks, a critic screens for verifier and solution leakage and guides recursive revision, and an executor follows qualified runbooks in fresh sandboxes. Across approximately 3K self-curated terminal tasks, three harnesses jointly solve 759 tasks, 34.3% more than the strongest individual harness in the recorded pool. RSR expands 2,001 successful source trajectories into 11,094 rewritten trajectories for supervised finetuning. Training on these traject"},{"id":"arxiv:2610.03574","pdf":"https://arxiv.org/pdf/2610.03574.pdf","submittedDate":"2026-10-02","source":"hf","arxiv":"https://arxiv.org/abs/2610.03574","tags":["Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03574","authors":["Alham Fikri Aji","Faiz Rizki Ramadhan","Zayd M. K. Zuhri","Seung Hun Eddie Han","Ryandito Diandaru","Qinrong Cui","Jan Christian Blaise Cruz","Badrinath Chandana","Peerawat Chomphooyod","Ahmed Attia","Jonibek Mansurov","Emilio Villa-Cueva","Canh Duong Nguyen","Imran Turganov","Minghao Wu","Peerat Limkonchotiwat","Irina Nikishina"],"hfUrl":"https://huggingface.co/papers/2610.03574","topics":["Evaluation"],"date":"2026-10-05","upvotes":8,"title":"HyperBrowseComp: A Multilingual and Multimodal Stress Test for Web-Browsing Agents","abstract":"We introduce HyperBrowseComp, a multilingual and multimodal browsing benchmark comprising 423 manually authored and human-validated questions across 13 languages, written by native or highly proficient speakers. Questions are designed to be extremely challenging. Each question targets a concise, publicly verifiable answer whose discovery requires locating obscure evidence, following multi-step clue chains, or inspecting heterogeneous sources such as videos, scanned documents, images, or maps. Easier questions are filtered out by evaluating them with models without internet access to reduce the likelihood that they can be answered with parametric knowledge alone. We evaluate several models using provider-native search and a shared external retrieval harness under a common agent protocol. To contextualize model performance and effort, we also conduct a human evaluation on a sample of the q"},{"id":"arxiv:2610.03664","pdf":"https://arxiv.org/pdf/2610.03664.pdf","submittedDate":"2026-10-02","source":"hf","arxiv":"https://arxiv.org/abs/2610.03664","tags":["Reasoning","Evaluation","Alignment"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03664","authors":["Linghui Shen","Tinghui Zhu","Sheng Zhang","Muhao Chen"],"hfUrl":"https://huggingface.co/papers/2610.03664","topics":["Reasoning","Evaluation","Alignment"],"date":"2026-10-05","upvotes":4,"title":"ProAR: Learning Prospective Reasoning with Autoregressive Video Models","abstract":"Autoregressive (AR) video models excel at causal generation, but their reliance on next-chunk prediction confines them to a short-sighted, reactive paradigm. This limitation is particularly consequential for reasoning-oriented generation, where achieving a target outcome through valid intermediate states matters more than local visual plausibility. To address this challenge, we propose Learning Prospective Reasoning with Autoregressive Video Models (ProAR), a novel framework that transforms autoregressive video generation into a goal-oriented reasoning process. ProAR introduces two key components: (1) To anchor generation to the long-range outcome, we integrate goal-frame prediction into the autoregressive loop via an asymmetric attention mask, enabling the predicted goal frame to guide the generation of intermediate states without being disrupted by them. (2) To guide short-range transi"},{"id":"arxiv:2610.02824","pdf":"https://arxiv.org/pdf/2610.02824.pdf","submittedDate":"2026-10-02","source":"hf","arxiv":"https://arxiv.org/abs/2610.02824","tags":["Post-Training","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02824","authors":["Yuxuan Fan","Jaehong Yoon"],"hfUrl":"https://huggingface.co/papers/2610.02824","topics":["Post-Training","Evaluation"],"date":"2026-10-05","upvotes":4,"title":"MetaRubric: Learning to Reward for Rubric-Based Reinforcement Learning","abstract":"Rubric-based reinforcement learning extends reward-driven optimization to open-ended tasks by assigning partial credit to individual response requirements. However, rubric judges can assign a high criterion score even when the information or action it requires is absent from the response, a failure mode we term Vacuous Credit. Such awards persist after the required information is removed and can reverse the sign of a response's GRPO advantage. To address this problem, we introduce MetaRubric, which alternates evidence-aware policy optimization with response-guided rubric adaptation. We construct counterfactual counterparts by changing one task-relevant fact in each prompt. During policy optimization, credit is assigned only when the response contains sufficient evidence to satisfy the required rubric criterion. After each policy-optimization stage, current policy responses guide revision"},{"id":"arxiv:2610.02298","pdf":"https://arxiv.org/pdf/2610.02298.pdf","submittedDate":"2026-10-01","source":"hf","arxiv":"https://arxiv.org/abs/2610.02298","tags":["VLM Training","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02298","authors":["Ruihan Yu","Yu-Ju Tsai","Muyao Niu","Runyi Li","Lian Fu","Hanqing Liu","Zheng-Hui Huang","Yonghao Yu","Sho Kuno","Ming-Hsuan Yang","Kaipeng Zhang","Zhixiang Wang"],"hfUrl":"https://huggingface.co/papers/2610.02298","topics":["VLM Training","Evaluation"],"date":"2026-10-05","upvotes":4,"title":"EditHero: A Benchmark for Long-Horizon Part-Level 3D Editing and Vibe Modeling","abstract":"3D editing methods are usually tested on a single edit, yet an asset is built through a long sequence of revisions, each of which must implement the requested change while leaving everything else unchanged. We introduce EditHero, to our knowledge the first benchmark for long-horizon, part-level 3D editing, with natural-language instructions and target images for both geometry and texture. A deterministic assembly engine produces the exact target after every edit, and every sequence is reviewed by hand. We use EditHero to compare 2 opposite approaches to 3D editing. Non-agentic methods operate top down, regenerating the object from a learned 3D representation and inferring what to keep. In contrast, LLM/VLM agents operate bottom up, editing through code that inspects the mesh and rewrites only the parts required by instructions. The non-agentic methods often miss the requested change and "},{"id":"arxiv:2610.02304","pdf":"https://arxiv.org/pdf/2610.02304.pdf","submittedDate":"2026-10-01","source":"hf","arxiv":"https://arxiv.org/abs/2610.02304","tags":["Agent Safety","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02304","authors":["Ruiqi Zhang","Jiahao Wang","Mingxuan Li","Haichen Luo","Chaoting Wang","Guoyu Mou","Keyu Lai","Hanchao Lv","Jiaxu Wang","Yibo Zheng","Aijun Yang","Xiaohua Wang"],"hfUrl":"https://huggingface.co/papers/2610.02304","topics":["Agent Safety","Evaluation"],"date":"2026-10-05","upvotes":2,"title":"SimuVerity: Benchmarking Agents for Engineering-Grade Simulink Model Generation","abstract":"Existing Simulink benchmarks mainly evaluate whether generated models compile, execute, or resemble a reference model. These criteria do not establish whether a model satisfies its engineering requirements. We introduce SimuVerity, a benchmark of 101 text-to-executable Simulink model-generation tasks across ten engineering domains. For each task, executable-system profiles ground the engineering specification and four families of native simulation scenarios. A hierarchical evaluator first checks artifact delivery, native executability, and engineering qualification, then scores qualified models across six dimensions covering accuracy, output quality, mechanistic fidelity, control and causal integrity, operating-domain robustness, and dynamic response. We evaluate six agent systems with SimuVerity. The best system achieves an overall score of only 42.86. The results show that structural s"},{"id":"arxiv:2610.02388","pdf":"https://arxiv.org/pdf/2610.02388.pdf","submittedDate":"2026-10-01","source":"hf","arxiv":"https://arxiv.org/abs/2610.02388","tags":["VLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02388","authors":["Ran Dan","Si-Tong Wei","Pengfei Xiong","Wei Zhang","Yadong Mu","Peng-Shuai Wang"],"hfUrl":"https://huggingface.co/papers/2610.02388","topics":["VLM Training","Evaluation","Fine-tuning"],"date":"2026-10-05","upvotes":1,"title":"Octrees as an Explicit 3D Language","abstract":"Existing 3D large language models (LLMs) compromise on two fronts: they compress shapes into latent codebook indices or coordinate text, which removes spatial structure from what the model observes, and they acquire the 3D modality by fine-tuning the backbone, which overwrites its general language ability. We present OctLLM, which addresses both limitations. Geometry enters as an explicit 3D sequence of octree occupancy tokens. However, full octree sequences grow rapidly with depth; OctLLM therefore randomly empties penultimate-level nodes and omits descendants while preserving shape, yielding a shorter coordinate- and depth-anchored Sparse Octree (S-Octree) for position-aware mask-modeling generation and 3D understanding. On the other front, existing methods introduce a new modality with full fine-tuning or LoRA, but full fine-tuning is costly, LoRA limits 3D capacity, and both modify t"},{"id":"arxiv:2610.02788","pdf":"https://arxiv.org/pdf/2610.02788.pdf","source":"hf","arxiv":"https://arxiv.org/abs/2610.02788","tags":["Fine-tuning"],"url":"https://arxiv.org/abs/2610.02788","authors":["Xincheng He","Siyu Ma","Chang Yu","Yunuo Chen","Yanjia Huang","Ying Nian Wu","Yin Yang","Chenfanfu Jiang"],"hfUrl":"https://huggingface.co/papers/2610.02788","topics":["Fine-tuning"],"date":"2026-10-05","upvotes":1,"title":"Skill2Real: Agentic Skill Learning for Zero-Shot Sim-to-Real Robot Manipulation","abstract":"Transferring robotic skills from simulation to reality requires task knowledge that remains usable across differences in perception, dynamics, and embodiment. We introduce Skill2Real, an agentic policy framework that learns executable skills through a shared application programming interface (API). A Proposer-Verifier-Governor (PVG) loop uses privileged simulation evidence to diagnose outcomes and validate updates, while keeping learned skills grounded in public observations and API semantics. The Cerebellum first acquires local manipulation skills; the Brain then learns task-level composition with the Cerebellum frozen. Both memories transfer to the real robot without task-policy fine-tuning or skill-memory updates. As GPT-5.6 Sol learns skills on LIBERO-90, evaluating each frozen checkpoint with GPT-6 Astra raises LIBERO-Pro Long success from 2.0% to 56.3%, without training on Pro Long"},{"id":"arxiv:2610.03548","pdf":"https://arxiv.org/pdf/2610.03548.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03548","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","Reflection"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03548","authors":["Wenlong Zhang","Zhengbo Jiao","Chenxu Zhang","Lekang Jiang","SiYuan Ma","Qituan Zhang","Guo Chen","Linfeng Zhang"],"topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","Reflection","Data Engine"],"date":"2026-10-05","upvotes":0,"title":"Recursive Harness Self-Improvement for Frontier Reasoning Data Synthesis","abstract":"Generating progressively harder reasoning problems requires synthesis procedures that adapt as the task distribution evolves. Existing task-level recursion reuses generated problems as seeds but leaves the construction harness unchanged. We present task-harness co-evolution, a framework for recursive harness self-improvement (RSI) in reasoning-data synthesis. Online self-improvement converts intermediate solver failures into reusable skills during generation. Post-task self-improvement revises skills, prompts, and workflows after each batch, adopting candidates only when they generate harder valid tasks within a bounded cost increase. Model weights and verification criteria remain fixed. Across mathematics, coding, and science, mean solver accuracy decreases from 100.0% to 54.8% over fourteen evolution rounds. Ablations show that combining both update schedules produces harder tasks than"},{"id":"arxiv:2610.03476","pdf":"https://arxiv.org/pdf/2610.03476.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03476","tags":["VLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03476","authors":["Chenzhi Liu","Yue Zhang","Jiehong Lin","Jianan Wang","Bo Wang","Zhongrui Wang","Xiaojuan Qi"],"topics":["VLM Training","Reasoning","Planning","Evaluation","Fine-tuning","Reflection"],"date":"2026-10-05","upvotes":0,"title":"MobiAgent: Dual-Loop Recursive Policy Self-Improvement for Long-Horizon Mobile Manipulation","abstract":"Long-horizon mobile manipulation presents significant challenges due to compounding execution errors and capacity interference between locomotion and arm control. While recent Vision-Language-Action models excel at short-horizon tasks, they lack the hierarchical reasoning required for multi-stage objectives. Furthermore, existing hierarchical agents suffer from rigid sub-task mapping, inflexible replanning, and a lack of continuous learning. To address these limitations, we introduce MobiAgent, a dual-loop agentic framework that bridges robust deployment execution and recursive policy self-improvement. During deployment, the Inner Loop decouples high-level reasoning from low-level control through highly composable atomic skills. It employs Vision-Language models for receding-horizon planning and visual reflection, dynamically composing skills to ensure robust error recovery. These skills"},{"id":"arxiv:2610.02542","pdf":"https://arxiv.org/pdf/2610.02542.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02542","tags":["Agentic RAG","Agentic Search","Evaluation","Fine-tuning","World Model"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02542","authors":["Dhananjay Ashok","Shantanu Agarwal","Vivek Datla","Jonathan May","Alfy Samuel"],"topics":["Agentic RAG","Agentic Search","Evaluation","Fine-tuning","World Model"],"date":"2026-10-05","upvotes":0,"title":"How To Train Your World Model: Fine-tuning vs RAG for LM-based World Modeling","abstract":"World models (WMs) simulate the transition dynamics of environments, enabling agents to plan over the consequences of their actions. In text-based environments, fine-tuning a Language Model (LM) to serve as a WM has emerged as a dominant paradigm. However, despite the widespread success of non-parametric approaches such as Retrieval Augmented Generation (RAG), retrieval for LM-based world modelling remains underexplored. We conduct a systematic evaluation across five diverse environments spanning embodied, web navigation and social settings, comparing fine-tuning and RAG-based approaches for LM-based world modelling. Our study reveals that fine-tuning often outperforms RAG, with fine-tuned WMs enabling agents to obtain higher rewards on 15/20 settings. While both construction paradigms benefit from additional and more diverse exploration, RAG-based approaches prove more data-efficient, a"},{"id":"arxiv:2610.03099","pdf":"https://arxiv.org/pdf/2610.03099.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03099","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03099","authors":["Jinghan Zhao","Yiman Hu","Liang Wu","Jian Xu","Bo Zheng"],"topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-10-05","upvotes":0,"title":"Beyond Single Videos: Benchmarking and Active Evidence Seeking for E-Commerce Cross-Video Reasoning","abstract":"E-commerce videos are information-dense and frequently compared by consumers evaluating products and merchants assessing marketing strategies. However, existing multimodal models mainly focus on single-video understanding and have limited ability to compare information across videos. We introduce AdsCVR, the first e-commerce cross-video reasoning benchmark, containing 2,483 videos and 6,110 question-answer pairs across six reasoning dimensions. Cross- video reasoning requires models to locate fine-grained evidence among many redundant frames and integrate visual details, speech, and on-screen text. We therefore propose AdSeek, an agentic framework that dynamically selects visual and audio tools during multi-turn exploration, replacing static uniform sampling with active evidence acquisition. To address the sparse credit assignment of reinforcement learning, we develop an offline trajecto"},{"id":"arxiv:2610.02320","pdf":"https://arxiv.org/pdf/2610.02320.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02320","tags":["LLM Training","VLM Training","Computer Use","Evaluation","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02320","authors":["A. Said Gurbuz","Ahmed Nassar","Sunghwan Hong","Marc Pollefeys","Peter W. J. Staar"],"topics":["LLM Training","VLM Training","Computer Use","Evaluation","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"DeskForge: Dense Supervision from Desktop Environments for Computer-Use Agents","abstract":"Computer-use agents need to reliably ground action targets in complex desktop scenes, where multiple applications, overlapping windows, and visually similar controls compete for attention. Existing training data rarely pair such scenes with dense annotations or vary them in a controlled way. We introduce DeskForge, a controllable desktop environment that composes and explores real applications to generate large-scale supervision for computer-use agents. It varies application states, content, window layout, appearance, and resolution, and fuses screenshots, accessibility trees, and window geometry into dense element annotations while recording the outcome of each executed action. Using this environment, we construct DeskForge-1M, a corpus of 1.2M annotated desktop observations containing 159.7M element instances. We fine-tune four vision-language models on 200K grounding examples drawn fr"},{"id":"arxiv:2610.03215","pdf":"https://arxiv.org/pdf/2610.03215.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03215","tags":["Agentic Search","Agent Safety","LLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03215","authors":["Rasha Albalawi","Nuha Albadi","Hamzah Luqman","Asma Yamani","Maram Kurdi","Saad Ezzini","Ahmed Ashraf","Maged Al-Shaibani","Nora Alturayeif"],"topics":["Agentic Search","Agent Safety","LLM Training","Evaluation","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"StanceEval 2026: The Second Stance Detection Shared Task","abstract":"StanceEval 2026 is the second edition of the StanceEval shared task series on stance detection in Arabic social media text. Stance detection aims to identify a writer's stance toward a given topic. Given a tweet and a target, participating systems must determine whether the writer's stance is Favor, Against, or None. This edition focuses on cross-target generalization across two distinct evaluation tracks: Track 1 evaluates thematically related cross-target transfer (testing on Women Driving, related to Women Empowerment from training data), while Track 2 evaluates cross-domain transfer to completely unseen targets (E-Cars and Trimester System). The shared task attracted 80 registered teams from 12 countries. During the evaluation phase, 30 unique teams submitted entries, with 21 teams officially ranked in Track 1 and 13 in Track 2 following validation filtering, and 20 teams submitting "},{"id":"arxiv:2610.03136","pdf":"https://arxiv.org/pdf/2610.03136.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03136","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation","Alignment"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03136","authors":["Oliver Hauck","Mario Sanz-Guerrero","Katharina von der Wense"],"topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation","Alignment"],"date":"2026-10-05","upvotes":0,"title":"Investigating the Role of Reasoning-Language Alignment in Monolingual Retrieval-Augmented Generation","abstract":"Reasoning traces improve large language models (LLMs), but current models are trained to reason mostly in English. It has been shown that forcing a model to reason in another language degrades accuracy, even when the reasoning language matches the language of the prompt -- but only for a setting where the model reasons over a short prompt. Here, we ask whether the same holds for retrieval-augmented generation (RAG), where the model must read and integrate a large amount of retrieved evidence in the target language. To study this, we build a fully monolingual German RAG question-answering testbed over the fictional world of the tabletop role-playing game The Dark Eye, a domain that is richly documented in German but too niche for the model to answer from memory, so that it has to rely on retrieval. Varying the forced reasoning language of an agentic RAG system on this testbed, we find tha"},{"id":"arxiv:2610.02819","pdf":"https://arxiv.org/pdf/2610.02819.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02819","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02819","authors":["Ziyang Cheng","Yuhao Wang","Hongcheng Liu","Qimin Wu","Jingru Fan","Chen Qian","Yanfeng Wang","Yu Wang"],"topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"date":"2026-10-05","upvotes":0,"title":"Text-Centric Post-Training for Omni-Modal Reasoning","abstract":"Improving joint audio-visual reasoning in Omni Large Language Models typically incurs substantial data construction and training costs. Our diagnostics reveal multi-hop reasoning difficulties despite correct answers to all corresponding single-hop questions and suggest partial decoupling in the local optimization of perception and reasoning objectives. This motivates post-training with different emphases on these capabilities. Text-only reasoning training yields gains across data sources, model scales, and families. With the best-performing text-only configuration, supervised fine-tuning followed by reinforcement learning (RL) raises Qwen2.5-Omni-7B's geometric mean of nine reasoning scores by 25.83% over the base model, outperforming the complete native audio-visual route with 56.6% fewer GPU-hours. Training on data synthesized entirely by a text-only LLM raises this geometric mean by 2"},{"id":"arxiv:2610.03063","pdf":"https://arxiv.org/pdf/2610.03063.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03063","tags":["Post-Training","LLM Training","Hallucination","Fine-tuning","RL for LLM"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03063","authors":["Tiezheng Yu","Yuxin Jiang","Jinpeng Li","Shuning Sun","Fei Mi","Haoli Bai","Lifeng Shang"],"topics":["Post-Training","LLM Training","Hallucination","Fine-tuning","RL for LLM"],"date":"2026-10-05","upvotes":0,"title":"HARPO: Hallucination-Aware Reinforcement Learning for Faithful and Creative Language Generation","abstract":"Large Language Models (LLMs) are prone to generating hallucinated content, which compromises their reliability in knowledge-intensive tasks. To address this challenge without sacrificing creativity, we propose HARPO, a reinforcement learning framework designed to jointly optimize faithfulness and creativity. HARPO incorporates a Hallucination-Aware Generative Reward Model (HA-GRM), trained via verifiable feedback, to assess both faithfulness and writing quality. A Selective Activation Mechanism (SAM) activates writing rewards only for outputs judged hallucination-free by HA-GRM, while a data curriculum progressively shifts training from creative writing to hallucination-centric tasks. On RAGTruth, our Qwen3-4B-based HA-GRM achieves a response-level F1 score of 78.08%, compared with 66.37% for the supervised fine-tuning baseline. Experiments on Qwen2.5 and Qwen3 models from 1.7B to 8B par"},{"id":"arxiv:2610.03617","pdf":"https://arxiv.org/pdf/2610.03617.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03617","tags":["VLM Training","Hallucination","Evaluation","Alignment","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03617","authors":["Vasco Ramos","Sandra Godinho Silva","Joao Magalhaes","Ricardo Rei","Pedro Henrique Martins"],"topics":["VLM Training","Hallucination","Evaluation","Alignment","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"DEPICT: Scoring Text-to-Image Alignment by Answer Agreement","abstract":"Image-text alignment is a core problem in computer vision with applications in caption evaluation, hallucination detection, data curation, and the benchmarking of text-to-image (T2I) generators. As T2I models improve, benchmarking has become demanding, requiring metrics capable of finding a series of issues like missing objects, swapped attributes, miscounts, and ignored negations. Recent work addresses this by fine-tuning evaluators on preference data or by prompting a vision-language model, either holistically with the caption or with decomposed verification questions. However, existing approaches fall short: fine-tuned metrics remain bound to one backbone and training distribution; holistic metrics miss fine-grained details; and decomposed metrics rely on a fixed-YES assumption that penalizes faithful images whenever that assumption fails. In contrast, we propose DEPICT, a training-fr"},{"id":"arxiv:2610.02627","pdf":"https://arxiv.org/pdf/2610.02627.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02627","tags":["Agentic RAG","Agentic Search","Agent Safety","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02627","authors":["Feng Chen","Ritam Dutt","Atnaz Taheri","Alex Williams"],"topics":["Agentic RAG","Agentic Search","Agent Safety","Evaluation"],"date":"2026-10-05","upvotes":0,"title":"Lost in the Request: How Communication Variation Disrupts Retrieval and Action in Email Agents","abstract":"An email assistant should not complete less work simply because a user phrases the same request differently. Yet most benchmarks test each task with only one canonical request, leaving this form of robustness largely unmeasured. We test whether email assistants remain reliable when the requested information, available evidence, and expected outcome stay fixed, but the communication style or English variety changes. We construct validated variants along five communication-style axes and four rule-based dialect conditions, and evaluate them on three benchmarks: a retrieval-augmented generation (RAG) pipeline and two tool-using agents. Indirect requests reduce performance on all three benchmarks, while formal requests reduce performance on both agentic benchmarks. Examining the systems more closely shows that these failures have different causes. Verbose requests mainly hurt a lexical retri"},{"id":"arxiv:2610.02967","pdf":"https://arxiv.org/pdf/2610.02967.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02967","tags":["Post-Training","LLM Training","Hallucination","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02967","authors":["Yuanhao Ban","I-Hung Hsu","Anastasios Angelopoulos","Wei-Lin Chiang","Ion Stoica","Cho-Jui Hsieh"],"topics":["Post-Training","LLM Training","Hallucination","Evaluation"],"date":"2026-10-05","upvotes":0,"title":"Post-Training Frontier Text-to-Image Models by Composing Preference and Rubric Rewards","abstract":"Recent text-to-image generation models have achieved remarkable visual quality, but improving them through post-training remains challenging because no single reward signal captures the full range of human preference. In this work, we develop a simple and effective post-training recipe for open-domain text-to-image generation based on the composition of complementary reward signals. Our reward system consists of two main components: a preference reward, trained on large-scale human preference data using a Bradley-Terry objective to capture overall human aesthetic and perceptual preferences, and rubric-based rewards, which explicitly evaluate prompt faithfulness and other desirable properties while providing safeguards against reward hacking. A key challenge is how to combine these heterogeneous reward signals. We show that a naive weighted average leads to suboptimal optimization behavio"},{"id":"arxiv:2610.02525","pdf":"https://arxiv.org/pdf/2610.02525.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02525","tags":["Agentic Search","LLM Training","Reasoning","RL for LLM"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02525","authors":["Ankur Samanta","Yonathan Efroni","Paul Sajda","Kaveh Hassani","Anirudh Goyal"],"topics":["Agentic Search","LLM Training","Reasoning","RL for LLM"],"date":"2026-10-05","upvotes":0,"title":"Learning What to Investigate Next: Meta-Reasoning for Long-Horizon Research Agents","abstract":"Long-horizon research agents must decide both how to investigate and what to investigate next as evidence accumulates. This is hard to learn because such decisions are sparse in long execution traces, and their consequences may emerge several investigations later. We introduce Meta-reasoning for Iterative Research Agents (MIRA), a hierarchical architecture separating research allocation from execution. An outer-loop meta-reasoner curates context from a persistent research record, then writes a work order for the next investigation or ends the episode. A fresh inner-loop executor carries out each work order, making execution part of the transition between meta-reasoning actions. Without policy training, MIRA improves long-horizon inference and allocates additional compute more effectively in theorem proving and open-ended neural-architecture research. Its decision boundaries also provide "},{"id":"arxiv:2610.02378","pdf":"https://arxiv.org/pdf/2610.02378.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02378","tags":["Post-Training","Reasoning","Alignment","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02378","authors":["Meng Liang","Guanbo Feng","Haozhuang Chi","Shilong Zhao","Zhixin Xiong","Yuhang He","Wenfeng Han","Tianhao Zhao","Zhihong Ma","Ying Liu"],"topics":["Post-Training","Reasoning","Alignment","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"THPL: A Vision-to-Language Decision Support Framework for Rainbow Trout Feeding Management in RAS","abstract":"In Recirculating Aquaculture Systems (RAS), precision feeding is critical for minimizing costs and improving fish welfare. However, existing methods lack cognitive alignment between fish behaviors and management knowledge, impeding translation into executable, interpretable feeding decisions. To address this, we propose THPL, a generative feeding decision framework tailored for rainbow trout (Oncorhynchus mykiss) in RAS. First, Fishsort extracts trajectories to establish an Activity Coefficient (AC) quantifying feeding intensity. Second, a Hierarchical Behavior Encoder (HBE) models individual temporal progression and collective dynamics using Temporal and Set Transformers, transforming trajectory tensors into dual-evidence representations of explicit physical and implicit soft tokens. Finally, these tokens are integrated with environmental parameters, metadata, and expert rules to fine-t"},{"id":"arxiv:2610.03713","pdf":"https://arxiv.org/pdf/2610.03713.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03713","tags":["Reasoning","Hallucination","Evaluation","World Model"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03713","authors":["Nishit Anand","Ramani Duraiswami","Dinesh Manocha"],"topics":["Reasoning","Hallucination","Evaluation","World Model"],"date":"2026-10-05","upvotes":0,"title":"What Should World Models Forget? Stratified Retention for Continual Adaptation","abstract":"Continual learning treats degradation on previously seen data as evidence of failure, a convention inherited from settings with a stationary prediction target, where a correct label remains correct indefinitely. World models do not satisfy this condition. Their prediction target is the environment, which changes, so knowledge that was accurate when acquired may later become false, and discarding it is required behavior rather than a defect. Non-stationary ground truth is well studied in the concept drift literature and in the temporal factuality of language models, but has not been formulated for world models, which are distinctive in that they also encode knowledge that must never be revised. We argue that continual world models require retention stratified by invariance timescale, separating invariants such as physics and object permanence, which must never be revised, from instance-le"},{"id":"arxiv:2610.02480","pdf":"https://arxiv.org/pdf/2610.02480.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02480","tags":["Multi-Agent","Reasoning","Hallucination","Agent Framework"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02480","authors":["Yuyang Cheng","Raghav Kaushik Ravi","Srivarshinee Sridhar","Sriparna Saha","Akash Ghosh","Chirag Agarwal"],"topics":["Multi-Agent","Reasoning","Hallucination","Agent Framework"],"date":"2026-10-05","upvotes":0,"title":"MEA: A Reward-Driven Multi-Agent System for Faithful Model Explanations","abstract":"Recent years have seen the employment of a plethora of machine learning (ML) models in high-stakes domains, but they remain largely opaque to the practitioners who act on their predictions. While post-hoc explanation methods offer a lens into this model behavior, wielding them effectively demands expertise most domain experts lack: navigating high-dimensional outputs, selecting the best explanations, and synthesizing evidence across disparate tools. To this end, we present MEA, a multi-agent framework that removes the explanation knowledge barrier entirely: a Proposer agent selects and configures explanation tools based on the question and modality, while an Actor agent is optimized end-to-end against faithfulness, transforming the outputs into natural language explanations grounded in model behavior across tabular, text, and vision modalities. Further, we introduce diverse question type"},{"id":"arxiv:2610.02665","pdf":"https://arxiv.org/pdf/2610.02665.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02665","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02665","authors":["Zhihan Yang","Wei Guo","Jean-Marie Lemercier","Simon Welker","Yonggan Fu","Mohammad Mahdi Kamani","Sajad Norouzi","Julius Berner","Tomas Geffner","Karsten Kreis","Yongxin Chen","Molei Tao","John Thickstun","Pavlo Molchanov","Ante Jukić","Arash Vahdat","Morteza Mardani"],"topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"Large Language Continuous Diffusion Models","abstract":"Despite the success of discrete diffusion language models (dLMs) for fast parallel decoding, their non-smooth, high-dimensional space hinders trajectory steering for reasoning and inference acceleration. To overcome this, we present Sigma, the first large-scale (3B/8B) continuous dLM built on steerable, low-dimensional ODE/SDE latent trajectories. Trained blockwise via likelihood optimization, Sigma jointly denoises Gaussian-corrupted token embeddings while learning an optimal embedding geometry. To accelerate training, Sigma leverages pre-trained weights from autoregressive (AR) models for warm-starting. During inference, we identify classifier-free guidance and score temperature as essential for high-fidelity reasoning and coding. Across comprehensive math reasoning and coding evaluations against state-of-the-art discrete counterparts (masked dLMs and AR baselines), Sigma achieves comp"},{"id":"arxiv:2610.02438","pdf":"https://arxiv.org/pdf/2610.02438.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02438","tags":["Post-Training","LLM Training","Reasoning","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02438","authors":["Nickil Maveli","Antonio Vergari","Shay B. Cohen"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation"],"date":"2026-10-05","upvotes":0,"title":"Are you Synthesizing or Recalling? Evaluating LLMs on Algorithmic Code Retrieval","abstract":"Large language models (LLMs) have demonstrated strong performance in code generation, where success depends on both recalling relevant algorithmic knowledge and reasoning about how to apply it. However, existing LLM pipelines are opaque, with no explicit separation between these two components. We argue that for well-known algorithms whose canonical implementations are widely accessible in pretraining corpora, code generation is better measured as \\textit{parametric code retrieval}: reproducing a named algorithm from internalised knowledge rather than synthesizing a novel one. We introduce AlgoREval, a benchmark of 599 problems spanning classical 77 algorithms across 14 domains, 7 programming languages, and 4 graph-input representations to evaluate this capability in isolation, and assess 15 models (7B--34B parameters) in a zero-shot setting. We find substantial variation in retrieval ac"},{"id":"arxiv:2610.02359","pdf":"https://arxiv.org/pdf/2610.02359.pdf","submittedDate":"2026-10-01","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02359","tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02359","authors":["Doseok Jang","Jon Ander Campos","Youran Qi"],"topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"date":"2026-10-05","upvotes":0,"title":"Lexicographic Multi-Objective On-Policy Distillation","abstract":"Reinforcement learning from verifiable rewards (RLVR) usually optimizes answer correctness, yet useful language-model behavior also requires high-quality reasoning and concise responses. Existing multi-reward post-training methods typically scalarize rewards or combine specialists without explicitly protecting a reward priority order. This is problematic when trade-offs are asymmetric: conciseness, for example, should not improve at the cost of correctness. We introduce Lexicographic Multi-Objective On-Policy Distillation (LMOPD), a multi-teacher method for integrating reward-specialized policies under explicit priorities. For each student rollout, LMOPD selects the specialist for the first objective whose gate detects a deficiency, then locally projects its centered log-policy correction to remove components that oppose higher-priority specialists. We evaluate 30B-A3B mixture-of-experts"},{"id":"arxiv:2610.02926","pdf":"https://arxiv.org/pdf/2610.02926.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02926","tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02926","authors":["Riju Marwah","Ritvik Garimella","Khusham Bansal","Atishay Jain","Amit Sheth"],"topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"date":"2026-10-05","upvotes":0,"title":"Output Language Confusion under Multilingual Prompt Contamination","abstract":"Standard factual benchmarks assume clean monolingual prompts and exact-match scoring, two assumptions that break simultaneously in real-world multilingual deployment, from retrieval-augmented generation pipelines returning mixed-language passages to users pasting multilingual web content. We introduce Multilingual Distractor Interference (MDI), a lightweight and fully replicable evaluation protocol requiring no new data or annotation, in which factual questions are preceded by a semantically irrelevant foreign-language sentence, and evaluate five instruction-tuned LLMs across TruthfulQA and TriviaQA under eight distractor conditions (40,000 evaluations). Our central finding is a metric confound: for Llama-3.1-8B under a Hindi distractor, 58% of responses switch to Devanagari script, yielding a raw hallucination proxy of 0.710, but manual review reveals that 120 of 148 script-switched res"},{"id":"arxiv:2610.03421","pdf":"https://arxiv.org/pdf/2610.03421.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03421","tags":["Agentic RAG","Agentic Search","Reasoning","Alignment"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03421","authors":["Hang Gao","Wujiang Xu","Zhixing Zhang","Kai Mei","Jingyi Yang","Dimitris N. Metaxas"],"topics":["Agentic RAG","Agentic Search","Reasoning","Alignment"],"date":"2026-10-05","upvotes":0,"title":"CLIMB: Confidence-Guided Complementary Evidence for Multimodal Retrieval-Augmented Generation","abstract":"Multimodal large language models (MLLMs) have shown strong visual reasoning abilities, but knowledge-intensive visual question answering often requires external textual evidence beyond the image and the model's parametric knowledge. Existing multimodal RAG systems commonly rely on Top-$K$ retrieval or reranking, which may return redundant passages and provide limited control over whether an answer update is sufficiently supported by the retrieved evidence. We propose \\textit{CLIMB}, a training-free inference-time framework for multimodal RAG. CLIMB first constructs a compact complementary evidence pool using an MMR-style objective that balances query relevance and passage-level redundancy. It then performs confidence-controlled refinement within this fixed pool: an R/E/C critic scores passages by relevance, evidence specificity, and cross-modal alignment, while an evidence-grounded confi"},{"id":"arxiv:2610.02986","pdf":"https://arxiv.org/pdf/2610.02986.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02986","tags":["Post-Training","LLM Training","Evaluation","Alignment"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02986","authors":["Tao Shi","Chaoyi Xiang","Qiongkai Xu","Jey Han Lau"],"topics":["Post-Training","LLM Training","Evaluation","Alignment"],"date":"2026-10-05","upvotes":0,"title":"OLMo-Detect: A Multi-Stage, Confounder-Controlled Benchmark for Membership Inference on Large Language Models","abstract":"Membership inference on large language models (LLMs) aims to determine whether a given text sample was included in an LLM's training data, without access to its training corpus. Despite recent progress, existing benchmarks suffer from three limitations: limited coverage of training stages, insufficient distributional alignment between members and non-members, and lack of rigorous filtering of non-members against the training corpus. To address these limitations, we propose OLMo-Detect, a multi-stage, confounder-controlled benchmark built upon the fully open OLMo 2 pipeline. OLMo-Detect spans pre-training, mid-training, and post-training, explicitly aligns members and non-members on three key axes, and rigorously filters non-members via infini-gram. To assess robustness to distribution shifts, we further introduce OLMo-Detect (Shifted), a variant where members are misaligned with non-memb"},{"id":"arxiv:2610.02970","pdf":"https://arxiv.org/pdf/2610.02970.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02970","tags":["Multi-Agent","Planning","Hallucination","Agent Framework"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02970","authors":["Songtao Li","Yijia Zhang","Shidi Zhang","Jianyuan Yuan","Fengyu Zhang","Hongfei Lin"],"topics":["Multi-Agent","Planning","Hallucination","Agent Framework"],"date":"2026-10-05","upvotes":0,"title":"A Guideline-Augmented Multi-Agent Framework for Schema-as-Code Biomedical Named Entity Recognition","abstract":"Large language models (LLMs) have shown promising potential for biomedical named entity recognition (BioNER) through instruction following and in-context learning. However, existing LLM-based BioNER methods still face two key limitations. First, retrieved demonstrations and external biomedical knowledge provide limited support for dataset-specific annotation semantics, leaving entity boundaries, type scopes, and annotation conventions ambiguous. Second, free-form generation lacks sufficient structural control, often leading to invalid formats, hallucinated mentions, duplicated entities, and boundary errors. To address these limitations, we propose GAMA, a guideline-augmented multi-agent framework for schema-as-code BioNER. GAMA first induces candidate annotation rules from labeled training instances and verifies them against annotated data to construct reliable dataset-specific guideline"},{"id":"arxiv:2610.03176","pdf":"https://arxiv.org/pdf/2610.03176.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03176","tags":["LLM Training","Reasoning","Hallucination","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03176","authors":["Aarav Singh","Animesh Pathak","Navyansh Singh"],"topics":["LLM Training","Reasoning","Hallucination","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"Hindsight-Guided Rationale Distillation for Rare Disease Diagnosis","abstract":"We study hindsight-guided distillation for rare disease diagnosis on ZebraMap: a 1.5B student is fine-tuned on chain-of-thought traces from a 8B teacher that observes the ground-truth diagnosis during generation. Absolute accuracy remains low for all models - the task is hard at this scale - but within this ceiling a filtered variant (StudentF) achieves a small, statistically significant accuracy advantage over the teacher (p < 0.001), concentrated in better-represented diseases. The unfiltered student does not significantly outperform the teacher (p = 0.129), establishing that contamination filtering - not hindsight distillation alone - drives the gain. The gap traces to an artifact we term GT hallucination. Label-visible generation causes the teacher to embed \"ground truth is X\" phrases in its reasoning chain; SFT copies the pattern. At inference, the unfiltered student reproduces the "},{"id":"arxiv:2610.03625","pdf":"https://arxiv.org/pdf/2610.03625.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03625","tags":["LLM Training","Evaluation","Alignment","Data Engine"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03625","authors":["Darian Lee","Shannon Rumsey","Jack St. Clair","Xinyi Tang","Aditya Bansal","Yuanming Shi"],"topics":["LLM Training","Evaluation","Alignment","Data Engine"],"date":"2026-10-05","upvotes":0,"title":"FALCON: A Model and Dataset Agnostic Framework for Synthetic Data Generation for NL2SQL Pairs","abstract":"Relational databases are among the most widely deployed forms of structured knowledge, and natural language access to them requires grounding language onto schema entities and relations while handling the ambiguity inherent in how people phrase requests. Existing synthetic NL-to-SQL data generation methods largely ignore this ambiguity and produce oversimplified queries that fail to prepare models for the complexity of real-world structured knowledge access. We present FALCON, a framework that generates realistic, ambiguity-aware NL-to-SQL data matching the complexity of challenging real-world benchmarks, at low cost using compact open models. Our approach combines reserved-word SQL seeding and persona-based prompting to generate structurally complex queries, while alignment-based filtering preserves difficulty by distinguishing genuinely incorrect examples from complex but valid queries"},{"id":"arxiv:2610.02856","pdf":"https://arxiv.org/pdf/2610.02856.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.02856","tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.02856","authors":["Baohang Li","Xiaocheng Feng","Yichong Huang","Chengpeng Fu","Wenshuai Huo","Zekun Zhou","Zekun Yuan","Tingjia Zhang","Bing Qin"],"topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"date":"2026-10-05","upvotes":0,"title":"Adaptive Mutual Distillation for Balanced Multi-Task Post-Training of Large Language Models","abstract":"Multi-task post-training of large language models (LLMs) aims to improve performance across tasks with unequal amounts of training data. Existing methods focus primarily on balancing task contributions during single-model training. Different task-balancing strategies can produce models with complementary strengths, creating opportunities for mutual distillation. However, the usefulness of cross-model supervision can vary across tasks, transfer directions, and stages of training. We propose Adaptive Mutual Distillation (AMD), a collaborative post-training framework that jointly trains two models with different task-balancing strategies. AMD evaluates candidate adjustments to distillation weights through short training probes shared across tasks, then uses task-wise validation scores to select an adjustment for each task and transfer direction. Across six benchmarks and three LLM backbones"},{"id":"arxiv:2610.03665","pdf":"https://arxiv.org/pdf/2610.03665.pdf","submittedDate":"2026-10-02","source":"arxiv","arxiv":"https://arxiv.org/abs/2610.03665","tags":["Post-Training","LLM Training","Reasoning","Evaluation"],"announceDate":"2026-10-05","url":"https://arxiv.org/abs/2610.03665","authors":["Seo Hyun Kim","Sunwoo Hong","Younwoo Choi","Chen-Hao Chao","Se-Young Yun","Rahul G. Krishnan"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation"],"date":"2026-10-05","upvotes":0,"title":"Pivot-SD: Efficient Self-Distillation for Masked Diffusion Language Models","abstract":"Masked diffusion language models (dLMs) offer a promising parallel alternative to autoregressive models for complex reasoning. However, they face a distinct credit-assignment challenge, since a few commitments during denoising sharply reduce the uncertainty over the remaining masked positions and shape much of the response. Most post-training recipes for dLMs do not use this signal to decide which tokens to train on: they typically train on the final text or assign rewards to whole denoising steps, rather than selecting the individual commitments that shape the response. We introduce Pivot-SD, an efficient offline self-distillation framework that supervises only these high-impact commitments (pivots). Pivot-SD selects pivots using an information-gain metric measuring uncertainty reduction over the remaining masked positions. Pivots from successful trajectories are trained with cross-entr"}],"archive":[],"latestPath":"data/latest.json"};
